from functools import lru_cache

# Decode each ReLU as a symbolic threshold on Boolean channel signals.
x = sp.symbols("x0:10")
channels = list(x)

def threshold(coeffs, bias, cutoff=0):
    # Return the Boolean formula for bias + sum(coeffs[i]*v[i]) > cutoff.
    # Clear denominators and rewrite negative coefficients as positive
    # weights on complemented literals.
    scale = 2
    b = int(round(scale * float(bias)))
    cut = int(round(scale * float(cutoff)))
    terms, rhs = [], cut - b + 1
    for i, c in enumerate(coeffs):
        c = int(round(scale * float(c)))
        if c > 0:
            terms.append((sp.Symbol(f"v{i}"), c))
        elif c < 0:
            terms.append((sp.Not(sp.Symbol(f"v{i}")), -c))
            rhs += -c

    if rhs <= 0:
        return sp.true
    total = sum(w for _, w in terms)
    if rhs > total:
        return sp.false

    @lru_cache(None)
    def ge(k, need):
        if need <= 0:
            return sp.true
        if k == len(terms) or sum(w for _, w in terms[k:]) < need:
            return sp.false
        lit, w = terms[k]
        return sp.Or(
            sp.And(lit, ge(k + 1, need - w)),
            sp.And(sp.Not(lit), ge(k + 1, need)),
        )

    formula = ge(0, rhs)
    subst = {sp.Symbol(f"v{i}"): channels[i] for i in range(len(coeffs))}
    return sp.simplify_logic(formula.xreplace(subst), force=True)

