from sympy.logic.boolalg import And, Or, Not, Xor, BooleanTrue, BooleanFalse, simplify_logic

def arr(name):
    t = W[name]
    return t.reshape(tuple(TASK["checkpoints"]["target"]["tensors"][name]["shape"]))

def threshold(weights, bias, variables):
    # Symbolically construct sum(weights[i]*variables[i]) >= 1-bias,
    # using coefficient-threshold identities rather than input assignments.
    target = 1 - int(round(float(bias)))
    n = len(weights)
    lo = [0] * (n + 1)
    hi = [0] * (n + 1)
    for i in range(n - 1, -1, -1):
        lo[i] = lo[i + 1] + min(0, weights[i])
        hi[i] = hi[i + 1] + max(0, weights[i])

    memo = {}
    def rec(i, t):
        if hi[i] < t:
            return sp.false
        if lo[i] >= t:
            return sp.true
        if i == n:
            return sp.false
        key = (i, t)
        if key not in memo:
            z = variables[i]
            memo[key] = Or(And(z, rec(i + 1, t - weights[i])),
                           And(Not(z), rec(i + 1, t)))
        return memo[key]
    return rec(0, target)

def compact(expr):
    if expr in (sp.true, sp.false):
        return expr
    return simplify_logic(expr)

