def literals_expr(terms, is_and):
    # A term is (Boolean expression, polarity).
    parts = [e if positive else Not(e) for e, positive in terms]
    if not parts:
        return sp.true if is_and else sp.false
    return (And if is_and else Or)(*parts)

def decode_gate(coeffs, bias, exprs):
    """Recognize Boolean gates from exact affine coefficient identities."""
    merged = {}
    for c, e in zip(coeffs, exprs):
        if c == 0:
            continue
        # Combine duplicate channels and opposite-polarity channels.
        if e.func is Not:
            key, polarity = e.args[0], -1
        else:
            key, polarity = e, 1
        merged[key] = merged.get(key, 0) + c * polarity

    items = [(e, c) for e, c in merged.items() if c]
    if not items:
        if bias > 0:
            return sp.true
        raise ValueError("Unrecognized constant gate")

    # A single signed literal, including its negation.
    if len(items) == 1:
        e, c = items[0]
        if c == 1 and bias == 0:
            return e
        if c == -1 and bias == 1:
            return Not(e)

    # Exact threshold identities for a clause or conjunction of literals.
    if all(abs(c) == 1 for _, c in items):
        clause_literals = [(e, c == 1) for e, c in items]
        conjunction_literals = clause_literals
        nneg = sum(not positive for _, positive in clause_literals)
        npos = len(items) - nneg

        # ReLU is positive iff at least one literal is true.
        if bias == 1 - nneg:
            return literals_expr(clause_literals, False)

        # ReLU is positive iff every literal is true.
        if bias == -npos:
            return literals_expr(conjunction_literals, True)

        # Three-input majority: x+y+z-1 > 0.
        if len(items) == 3 and all(c == 1 for _, c in items) and bias == -1:
            from sympy.logic.boolalg import Xor
            a, b, c = [e for e, _ in items]
            return Or(And(a, b), And(a, c), And(b, c))

    raise ValueError("Gate does not match the exact Boolean coefficient identities")

